import { Mesh, PlaneGeometry, Object3D, Color, Vector2 } from 'three/webgpu';
import {
	MeshBasicNodeMaterial,
	uv,
	mix,
	add,
	mul,
	float,
	noise,
	positionWorld,
	attribute,
	cond,
	equal,
	lessThan,
	greaterThan,
	oscillate,
	rotateUV,
	rotate,
	rotateUVNode,
	rotateUVNode as UVRotateNode,
	rotateNode,
	rotateNode as RotateNode,
	UVNode,
	UVTransformNode,
	UVScaleNode,
	UVOffsetNode,
	UVNode as UV,
	UVTransformNode as UVTransform,
	UVScaleNode as UVScale,
	UVOffsetNode as UVOffset,
	UVNode,
	UVTransformNode,
	UVScaleNode,
	UVOffsetNode,
} from 'three/tsl';
import { gsap } from 'gsap';
import { createTextNode } from '@/text';

export default function createNode(config, ctx) {
	const root = new Object3D();
	root.position.set(0, 0, 0);
	root.rotation.set(0, 0, 0);
	root.scale.set(1, 1, 1);
	root.userData.handlers = {};

	// ---------- Background Plane ----------
	const bgGeom = new PlaneGeometry(7, 5.5);
	const gradientNode = mix(
		new Color('#0b0b10'),
		new Color('#14141a'),
		uv().y
	);
	const grainNode = mul(
		float(0.015),
		noise(mul(uv(), float(50)))
	);
	const bgColorNode = add(gradientNode, grainNode);
	const bgMat = new MeshBasicNodeMaterial({
		color: bgColorNode,
		transparent: true,
	});
	const bgMesh = new Mesh(bgGeom, bgMat);
	bgMesh.position.set(0, 0, 0);
	root.add(bgMesh);

	// ---------- Text Blocks ----------
	const blocks = [];

	// Helper to create a text block
	function makeTextBlock(text, typ, yPos, extra = {}) {
		const {
			family,
			fontSize,
			fontWeight,
			letterSpacing,
			lineHeight,
			color = '#16161d',
			align = 'left',
			maxWidth = null,
		} = typ;

		const txtObj = createTextNode(text, {
			fontFamily: family,
			fontSize,
			fontWeight,
			letterSpacing,
			lineHeight,
			color,
			align,
			maxWidth,
			position: new Vector2(-3.1, yPos),
			atlas: ctx.fontAtlas,
			atlasRegion: { index: 0, rect: new Vector2(0, 0), size: new Vector2(512, 320) },
			...extra,
		});

		// initial state for entrance animation
		txtObj.position.y += 0.4;
		if (txtObj.material) {
			txtObj.material.transparent = true;
			txtObj.material.opacity = 0;
		}
		root.add(txtObj);
		return txtObj;
	}

	// Kicker
	const kickerSpec = {
		family: 'JetBrains Mono',
		fontSize: 18,
		fontWeight: 700,
		letterSpacing: 0.12,
		lineHeight: 1.4,
		color: '#16161d',
	};
	const kicker = makeTextBlock('NOVA ATELIER / JOURNAL', kickerSpec, 1.7);
	blocks.push(kicker);

	// Hero line 1 (shadow)
	const heroSpec = {
		family: 'Lora',
		fontSize: 124,
		fontWeight: 600,
		letterSpacing: -0.015,
		lineHeight: 0.98,
		color: '#16161d',
	};
	const hero1Shadow = makeTextBlock('PRECISION IS', heroSpec, 0.9, { depthOffset: -0.02 });
	hero1Shadow.position.z = -0.02;
	blocks.push(hero1Shadow);

	// Hero line 1 (foreground)
	const hero1 = makeTextBlock('PRECISION IS', heroSpec, 0.9, { color: '#e8ecf2' });
	blocks.push(hero1);

	// Hero line 2 (shadow)
	const hero2Shadow = makeTextBlock('A HABIT.', heroSpec, 0.25, { depthOffset: -0.02 });
	hero2Shadow.position.z = -0.02;
	blocks.push(hero2Shadow);

	// Hero line 2 (foreground)
	const hero2 = makeTextBlock('A HABIT.', heroSpec, 0.25, { color: '#e8ecf2' });
	blocks.push(hero2);

	// Body
	const bodySpec = {
		family: 'JetBrains Mono',
		fontSize: 26,
		fontWeight: 400,
		letterSpacing: 0,
		lineHeight: 1.55,
		color: '#e8ecf2',
	};
	const body = makeTextBlock(
		'Notes from the bench: tolerances, tempering, and the case for slower watchmaking.',
		bodySpec,
		-0.8,
		{ maxWidth: 4.5 }
	);
	blocks.push(body);

	// Caption
	const captionSpec = {
		family: 'JetBrains Mono',
		fontSize: 18,
		fontWeight: 400,
		letterSpacing: 0.08,
		lineHeight: 1.4,
		color: '#e8ecf2',
	};
	const caption = makeTextBlock('ISSUE 12 / JULY 2026', captionSpec, -1.9);
	blocks.push(caption);

	// ---------- Underline Rule ----------
	const ruleGeom = new PlaneGeometry(2.2, 0.05);
	const ruleMat = new MeshBasicNodeMaterial({
		color: new Color('#ff2a38'),
		emissive: float(1.2),
		transparent: true,
	});
	const ruleMesh = new Mesh(ruleGeom, ruleMat);
	ruleMesh.position.set(-3.1 + 2.2 / 2, -0.15, 0);
	ruleMesh.scale.set(0, 1, 1); // start collapsed on X
	root.add(ruleMesh);

	// ---------- Animation ----------
	const tl = gsap.timeline();

	blocks.forEach((blk, i) => {
		const targetY = blk.position.y - 0.4;
		tl.fromTo(
			blk.position,
			{ y: blk.position.y },
			{
				y: targetY,
				duration: 0.7,
				ease: 'power3.out',
				delay: i * 0.08,
			},
			0
		);
		if (blk.material && blk.material.opacity !== undefined) {
			tl.fromTo(
				blk.material,
				{ opacity: 0 },
				{ opacity: 1, duration: 0.7, ease: 'power3.out', delay: i * 0.08 },
				0
			);
		}
	});

	// After hero lines finish, animate underline rule
	const heroLandingTime = (blocks.indexOf(hero1) + 1) * 0.08 + 0.7;
	tl.to(
		ruleMesh.scale,
		{
			x: 1,
			duration: 0.5,
			ease: 'power2.out',
		},
		heroLandingTime
	);

	// ---------- Cleanup ----------
	root.userData.cleanup = () => {
		// dispose geometries and materials
		bgGeom.dispose();
		bgMat.dispose();
		ruleGeom.dispose();
		ruleMat.dispose();

		blocks.forEach((blk) => {
			if (blk.geometry) blk.geometry.dispose();
			if (blk.material) blk.material.dispose();
		});

		// kill GSAP timeline
		tl.kill();
	};

	return root;
}
